                    s = 'Türk Lirası borcunuz için ödenmesi gereken minimum tutar ' + Z + '.'
            elif k == 'none_paid':
                s = 'Türk Lirası borcunuz ' + X + ', ödenmesi gereken minimum tutar ' + Z + '.'
            elif k == 'min_paid':
