def ask(S, O, stage, q, short, prefix):
    if S.get('stage') != stage or S.get('q') != q:
        S['tries'] = 0
        S['silences'] = 0
        S['broken'] = 0
        S['chat'] = 0
    S['stage'] = stage
    S['q'] = q
    S['short'] = short or q
    say = (prefix + ' ' + q).strip()
    O['say'] = say
    O['route'] = 'talk_' + stage
    S['last_say'] = say


def finish(O, text, route):
    O['final'] = text.strip()
    O['route'] = route


def try_fail(S, O, prefix, again):
    S['tries'] = int(S.get('tries') or 0) + 1
    if S['tries'] >= TRIES:
        finish(O, S_FAIL3, 'end_menu')
        return
    q = again or S.get('q') or ''
    O['say'] = (prefix + ' ' + q).strip()
    O['route'] = 'talk_' + S.get('stage')
    S['last_say'] = O['say']


def reask(S, O, prefix):
    O['say'] = (prefix + ' ' + (S.get('q') or '')).strip()
    O['route'] = 'talk_' + S.get('stage')


def main_cards(S):
    return [i for i, c in enumerate(S.get('cards') or []) if c.get('main')]


def unread(S):
    return [i for i in main_cards(S) if i not in (S.get('read') or [])]


def start_read(S, O, V, idx, prefix):
    cards = S['cards']
    S['cur'] = idx
    S['cand'] = []
    S['sub'] = ''
    S['dbuf'] = ''
    O['cur_card'] = cards[idx]['num']
    O['route'] = 'bal_' + str(min(idx, BAL_NODES - 1))
    S['pend'] = 'bal'
    S['read_prefix'] = prefix
    left = [i for i in unread(S) if i != idx]
    if not S.get('email_known') and S.get('after_read', '') in ('', 'email') and (not left or S.get('focus') or S.get('after_read') == 'email'):
        O['need_email'] = 'yes'


def choose(S, O, V, idx, prefix):
    cards = S['cards']
    if not cards[idx].get('main'):
        S['cand'] = []
        S['sub'] = ''
        ask(S, O, 'card', select_question(cards, unread(S)), 'Hangi kartınızın borcunu öğrenmek istersiniz?',
            prefix + ' Bu kart için ekstre borcu sorgulanabilecek uygun bir kart bulunmuyor. Lütfen başka bir kartınızı seçin.')
        return
    start_read(S, O, V, idx, prefix)


def resolve_card(S, O, V, said, digits, prefix, costs):
    """returns True when it produced output"""
    cards = S.get('cards') or []
    d = re.sub(r'\D', '', words_to_digits(digits or '')) if digits else ''
    if not d and said:
        d2 = re.sub(r'\D', '', words_to_digits(said))
        if len(d2) >= 4:
            d = d2
    sub = S.get('sub') or ''
    if d:
        need = 16 if sub == 'd16' else (6 if sub == 'd6' else 4)
        buf = (S.get('dbuf') or '') + d
        if len(d) in (4, 6, 16) and len(buf) != need:
            buf = d
        if len(buf) < need and len(buf) not in (4, 6):
            S['dbuf'] = buf
            O['say'] = (prefix + ' Lütfen kalan haneleri de söyler misiniz?').strip()
            O['route'] = 'talk_' + (S.get('stage') or 'card')
            return True
        if len(buf) > 16 or (len(buf) > 6 and len(buf) < 16 and sub == 'd16'):
            if len(buf) < 16:
                S['dbuf'] = buf
                reask(S, O, prefix + ' Lütfen hanelerin tamamını söyler misiniz?')
                return True
        S['dbuf'] = ''
        if len(buf) > 16:
            buf = buf[-16:]
        if len(buf) not in (4, 6, 16):
            buf = buf[-4:] if len(buf) < 6 else buf[-6:]
        hits = match_digits(buf, cards, S.get('cand') or [])
        if not hits and S.get('cand'):
            hits = match_digits(buf, cards, [])
            if hits:
                S['cand'] = []
                S['sub'] = ''
        if len(hits) == 1:
            choose(S, O, V, hits[0], prefix)
            return True
        if len(hits) > 1:
            S['cand'] = hits
            if len(buf) == 4:
                S['sub'] = 'd6'
                ask(S, O, 'card', 'Son dört hanesi ' + digits_tr(buf) + ' olan birden fazla kartınız var. Kartınızın son altı hanesini söyler misiniz?', 'Kartınızın son altı hanesini söyler misiniz?', prefix)
            else:
                S['sub'] = 'd16'
                ask(S, O, 'card', 'Son altı hanesi aynı olan birden fazla kartınız var. Kart numaranızı söyler misiniz?', 'Kart numaranızı söyler misiniz?', prefix)
            return True
        S['tries'] = int(S.get('tries') or 0) + 1
        if S['tries'] >= TRIES:
            finish(O, S_FAIL3, 'end_menu')
            return True
        if S.get('stage') != 'card':
            S['stage'] = 'card'
            S['q'] = select_question(cards, unread(S))
            S['short'] = 'Hangi kartınızın borcunu öğrenmek istersiniz?'
        reask(S, O, prefix + ' Söylediğiniz numarayla eşleşen bir kartınız bulunmuyor.')
        return True
    if said:
        hits = match_name(said, cards)
        if S.get('cand') and hits:
            inter = [i for i in hits if i in S['cand']]
            hits = inter or hits
        if len(hits) == 1:
            choose(S, O, V, hits[0], prefix)
            return True
        if len(hits) > 1:
            names = distinct([cards[i].get('name') for i in hits])
            S['cand'] = hits
            if len(names) == 1:
                S['sub'] = 'd4'
                nm = spoken_name(names[0]) or 'Bu'
                ask(S, O, 'card', nm + ' isimli birden fazla kartınız var. Kartınızın son dört hanesini söyler misiniz?', 'Kartınızın son dört hanesini söyler misiniz?', prefix)
            else:
                S['sub'] = ''
                sp = distinct([spoken_name(n) for n in names])
                ask(S, O, 'card', 'Bu isimle eşleşen ' + join_names(sp) + ' kartlarınız var. Hangisinin borcunu öğrenmek istersiniz?', 'Hangi kartınızın borcunu öğrenmek istersiniz?', prefix)
            return True
        S['cand'] = []
        S['sub'] = ''
        names = distinct([spoken_name(cards[i].get('name')) for i in main_cards(S)])
        q = 'Kartlarınız şunlar: ' + join_names(names) + '. Hangi kartınızın borcunu öğrenmek istersiniz?' if names else select_question(cards, unread(S))
        if S.get('stage') != 'card':
            ask(S, O, 'card', q, 'Hangi kartınızın borcunu öğrenmek istersiniz?', prefix + ' Bu isimde bir kartınız bulunmuyor.')
            if costs:
                S['tries'] = 1
            return True
        S['q'] = q
        try_fail(S, O, prefix + ' Bu isimde bir kartınız bulunmuyor.', q)
        return True
    return False


def offer_entry(S, O, V, prefix):
    if not S.get('email_known'):
        S['pend'] = 'email'
        S['cont'] = 'offer'
        S['stash'] = prefix
        O['route'] = 'api_email'
        return
    if S.get('email_failed'):
        finish(O, prefix + ' ' + S_SVC, 'end_agent')
        return
    t = offer_sentence(bool(S.get('email')), not S.get('week_changed'))
    if not t:
        finish(O, prefix + ' ' + S_MENU, 'end_menu')
        return
    ask(S, O, 'offer', t, t, prefix)


def email_entry(S, O, V, prefix):
    if not S.get('email_known'):
        S['pend'] = 'email'
        S['cont'] = 'email'
        S['stash'] = prefix
        O['route'] = 'api_email'
        return
    if S.get('email_failed'):
        finish(O, prefix + ' ' + S_SVC, 'end_agent')
        return
    if not S.get('email'):
        p = prefix + ' Bankamızda kayıtlı bir e-posta adresiniz bulunmadığı için ekstrenizi gönderemiyorum.'
        if not S.get('week_changed'):
            t = 'Hesap kesim tarihinizi değiştirebilirim.'
            ask(S, O, 'offer', t, t, p)
        else:
            finish(O, p + ' ' + S_MENU, 'end_menu')
        return
    if not S.get('cur_sd'):
        finish(O, prefix + ' Kartınızın henüz kesilmiş bir ekstresi bulunmuyor. ' + S_MENU, 'end_menu')
        return
    S['esub'] = 'confirm'
    q = 'Ekstrenizi ' + email_spoken(S['email']) + ' göndermemi ister misiniz?'
    ask(S, O, 'email', q, q, prefix)


def week_entry(S, O, V, prefix, pre):
    if S.get('week_changed'):
        finish(O, prefix + ' Hesap kesim tarihinizi yılda bir kez değiştirebilirsiniz. ' + S_MENU, 'end_menu')
        return
    S['pre_week'] = pre
    S['stash'] = prefix
    S['pend'] = 'wget'
    O['cur_card'] = S['cards'][S['cur']]['num']
    O['route'] = 'api_wget'


def go_preview(S, O, w, prefix):
    S['wk_new'] = w
    S['stash'] = prefix
    S['pend'] = 'wdec'
    O['wk_new'] = str(w)
    O['wk_day'] = str(S['wk']['day'])
    O['cur_card'] = S['cards'][S['cur']]['num']
    O['route'] = 'api_wdec'


def after_reading(S, O, V, text, kind):
    if kind == 'debt':
        S['any_debt'] = 1
    ar = S.get('after_read') or ''
    S['after_read'] = ''
    if ar == 'email':
        email_entry(S, O, V, text)
        return
    if ar == 'week':
        week_entry(S, O, V, text, 0)
        return
    if unread(S) and not S.get('focus'):
        q = 'Başka bir kartınızın borcunu öğrenmek ister misiniz?'
        ask(S, O, 'another', q, q, text)
        return
    if not S.get('any_debt'):
        finish(O, text + ' ' + S_MENU, 'end_menu')
        return
    S['focus'] = ''
    offer_entry(S, O, V, text)


def handle_bank(S, O, V, pend, today):
    if pend == 'list':
        body = read_tree(V, 'api_list_response')
        st = V.get('api_list_status_code', V.get('api_list_response.status_code'))
        rc = str((body.get('result') or dict()).get('returnCode') or '') if isinstance(body.get('result'), dict) else ''
        S['listed'] = 1
        if rc == 'FB_IVR_CHANNEL_102' or str(st) == '404':
            finish(O, S_NOCARD, 'end_menu')
            return
        if not call_ok(body, st):
            finish(O, S_SVC, 'end_agent')
            return
        S['cards'] = list_cards(body)
        if not main_cards(S):
            finish(O, S_NOCARD, 'end_menu')
            return
        handle_bank_list_again(S, O, V, today)
        return
    if pend == 'bal':
        idx = S.get('cur', 0)
        node = 'bal_' + str(min(idx, BAL_NODES - 1))
        body = read_tree(V, node + '_response')
        st = V.get(node + '_status_code', V.get(node + '_response.status_code'))
        if not call_ok(body, st):
            finish(O, S_SVC, 'end_agent')
            return
        bal = body.get('data') if isinstance(body.get('data'), dict) else dict()
        S['cur_sd'] = str(bal.get('statementDate') or '')
        if S['cur_sd'] in ('null', 'None'):
            S['cur_sd'] = ''
        text, kind = reading(S['cards'][idx], bal, today, S.get('focus') or '')
        text = ((S.get('read_prefix') or '') + ' ' + text).strip()
        rd = S.get('read') or []
        if idx not in rd:
            rd.append(idx)
        S['read'] = rd
        after_reading(S, O, V, text, kind)
        return
    if pend == 'email':
        cont = S.get('cont') or 'offer'
        prefix = S.get('stash') or ''
        if cont == 'offer':
            offer_entry(S, O, V, prefix)
        else:
            email_entry(S, O, V, prefix)
        return
    if pend == 'pdf':
        body = read_tree(V, 'api_pdf_response')
        st = V.get('api_pdf_status_code', V.get('api_pdf_response.status_code'))
        d = body.get('data') if isinstance(body.get('data'), dict) else dict()
        if call_ok(body, st) and str(d.get('exitState') or '').upper() == 'DONE':
            finish(O, 'Ekstreniz kayıtlı e-posta adresinize gönderildi. ' + S_MENU, 'end_menu')
        else:
            finish(O, S_SVC, 'end_agent')
        return
    if pend == 'wget':
        body = read_tree(V, 'api_wget_response')
        st = V.get('api_wget_status_code', V.get('api_wget_response.status_code'))
        d = body.get('data') if isinstance(body.get('data'), dict) else dict()
        if not call_ok(body, st):
            finish(O, (S.get('stash', '') + ' ' + S_SVC_WEEK).strip(), 'end_agent')
            return
        try:
            cw = int(float(str(d.get('statementWeek'))))
        except Exception:
            cw = 0
        try:
            day = int(float(str(d.get('statementDay'))))
        except Exception:
            day = 0
        card = S['cards'][S['cur']]
        rel = str(d.get('relationType') or '')
        rnum = str(d.get('relatedCardNumber') or '')
        rname = spoken_name(d.get('relatedCardProductName'))
        S['wk'] = dict(cur=cw, day=day, rel=rel if rel in ('M', 'C') else '', rname=rname, rl4=rnum[-4:] if rnum else '')
        intro = card_intro(card) + 'kartınız'
        other = ('sonu ' + digits_tr(rnum[-4:]) + ' ile biten ' if rnum else '') + (rname + ' ' if rname else '') + 'kartınızın'
        if S['wk']['rel'] == 'M':
            subj = intro + ' ile buna bağlı ' + other
        elif S['wk']['rel'] == 'C':
            subj = intro + ' ile bu kartın bağlı olduğu ' + other
        else:
            subj = intro + 'ın'
        info = subj + ' hesap kesim tarihi her ayın ' + (ORD[cw] if 1 <= cw <= 4 else str(cw)) + ' haftası olarak tanımlı.'
        if date_tr(d.get('nextStatementDate')) and date_tr(d.get('nextLastPayDate')):
            info = info + ' Bir sonraki hesap kesim tarihiniz ' + date_tr(d.get('nextStatementDate')) + ', son ödeme tarihiniz ' + date_tr(d.get('nextLastPayDate')) + '.'
        prefix = ((S.get('stash') or '') + ' ' + info).strip()
        pw = int(S.get('pre_week') or 0)
        if 1 <= pw <= 4 and pw != cw:
            go_preview(S, O, pw, prefix)
            return
        q = 'Hesap kesim tarihinizi değiştirmek ister misiniz?'
        ask(S, O, 'wwant', q, q, prefix)
        return
    if pend == 'wdec':
        body = read_tree(V, 'api_wdec_response')
        st = V.get('api_wdec_status_code', V.get('api_wdec_response.status_code'))
        d = body.get('data') if isinstance(body.get('data'), dict) else dict()
        if not call_ok(body, st) or str(d.get('responseCode', '0')) not in ('0', '0.0'):
            finish(O, (S.get('stash', '') + ' ' + S_SVC_WEEK).strip(), 'end_agent')
            return
        S['prev'] = dict(sd=date_tr(d.get('statementDate')), due=date_tr(d.get('statementDueDate')))
        w = int(S.get('wk_new') or 0)
        wk = S.get('wk') or dict()
        joint = ''
        if wk.get('rel') == 'M':
            joint = 'Bu değişiklik kartınıza bağlı ' + (wk.get('rname') + ' ' if wk.get('rname') else '') + 'kartınızı da etkileyecek. '
        elif wk.get('rel') == 'C':
            joint = 'Bu değişiklik kartınızın bağlı olduğu ' + (wk.get('rname') + ' ' if wk.get('rname') else '') + 'kartınızı da etkileyecek. '
        q = joint + 'Yeni hesap kesim haftanız her ayın ' + ORD[w] + ' haftası olacak. Yeni hesap kesim tarihiniz ' + S['prev']['sd'] + ', son ödeme tarihiniz ' + S['prev']['due'] + ' olacak. Onaylıyor musunuz?'
        ask(S, O, 'wconf', q, 'Değişikliği onaylıyor musunuz?', S.get('stash') or '')
        return
    if pend == 'wchg':
        body = read_tree(V, 'api_wchg_response')
        st = V.get('api_wchg_status_code', V.get('api_wchg_response.status_code'))
        d = body.get('data') if isinstance(body.get('data'), dict) else dict()
        if call_ok(body, st) and str(d.get('exitState') or '').upper() == 'OK' and str(d.get('responseCode', '0')) in ('0', '0.0'):
            S['week_changed'] = 1
            w = int(S.get('wk_new') or 0)
            card = S['cards'][S['cur']]
            t = card_intro(card) + 'kartınızın hesap kesim haftası her ayın ' + ORD[w] + ' haftası olarak değiştirildi. Yeni hesap kesim tarihiniz ' + S['prev']['sd'] + ', son ödeme tarihiniz ' + S['prev']['due'] + '.'
            S['stage'] = 'after'
            S['q'] = ''
            S['short'] = ''
            S['tries'] = 0
            O['say'] = t
            S['last_say'] = t
            O['route'] = 'talk_after'
        else:
            finish(O, S_SVC_WEEK, 'end_agent')
        return


SIDE = dict(robot="Evet, ben Freya Bank'ın sesli asistanıyım.", pin_given='Bu bilgiyi kullanmıyorum; bankamız sizden hiçbir zaman şifre istemez.',
            instructions_request='Bu bilgiyi paylaşamıyorum.')


def handle_msg(S, O, V, today):
    if not S.get('stage'):
        S['stage'] = 'open'
        S['q'] = 'Kredi kartı ekstre borcunuzla ilgili size nasıl yardımcı olabilirim?'
        S['short'] = S['q']
        S['last_say'] = GREETING
    stage = S.get('stage')
    kind = str(V.get('kind_' + stage) or 'none')
    side = str(V.get('side_q') or 'none')
    said = str(V.get('card_said') or '').strip()
    digits = str(V.get('digits_said') or '').strip()
    wsaid = str(V.get('week_said') or '').strip()
    fig = str(V.get('figure') or 'none')
    S['turns'] = int(S.get('turns') or 0) + 1
    if S['turns'] > TURN_LIMIT:
        finish(O, S_FAIL3, 'end_menu')
        return
    prefix = SIDE.get(side, '')
    if kind == 'third_party':
        finish(O, S_LOGIN, 'end_login')
        return
    if kind == 'non_turkish':
        finish(O, S_MENU_A, 'end_menu')
        return
    if kind == 'agent_request':
        finish(O, S_AGENT, 'end_agent')
        return
    if kind == 'pay':
        finish(O, S_PAY, 'end_agent')
        return
    if kind == 'dispute' and stage == 'open' and not S.get('read'):
        kind = 'want_debt'
    if kind == 'dispute':
        finish(O, S_DISPUTE, 'end_agent')
        return
    if kind == 'switch_transaction':
        finish(O, S_MENU, 'end_menu')
        return
    if kind == 'goodbye_thanks':
        finish(O, S_MENU, 'end_menu')
        return
    if stage == 'open':
        if kind == 'out_of_scope':
            S['oos_back'] = 'open'
            S['oos_q'] = 'Kredi kartı ekstre borcunuzla ilgili size nasıl yardımcı olabilirim?'
            S['stage'] = 'oos'
            ask(S, O, 'oos', S_OOS, 'Sizi ana menüye aktarmamı ister misiniz?', prefix)
            return
        if kind in ('want_debt', 'all_cards', 'want_email', 'want_week', 'card_named'):
            S['open_msg'] = dict(card=said, digits=digits, all=(kind == 'all_cards'), prefix=prefix,
                                 after_read=('email' if kind == 'want_email' else ('week' if kind == 'want_week' else '')),
                                 focus=(fig if fig in ('min_only', 'due_only') else ''))
            if S.get('listed'):
                S['pend'] = ''
                handle_bank_list_again(S, O, V, today)
                return
            S['pend'] = 'list'
            O['route'] = 'api_list'
            return
    if stage == 'after':
        if kind == 'undo':
            finish(O, 'Değişikliğiniz gerçekleşti, bu görüşmede geri alamıyorum. ' + S_MENU, 'end_menu')
            return
        if kind == 'when_applies':
            finish(O, 'Yeni hesap kesim tarihiniz ' + (S.get('prev') or dict()).get('sd', '') + '. ' + S_MENU, 'end_menu')
            return
        if kind == 'week':
            finish(O, 'Hesap kesim tarihinizi yılda bir kez değiştirebilirsiniz. ' + S_MENU, 'end_menu')
            return
        if kind == 'angry':
            finish(O, 'Sizi anlıyorum. ' + S_MENU, 'end_menu')
            return
        finish(O, (prefix + ' ' + S_MENU).strip(), 'end_menu')
        return
    if stage in ('card', 'another', 'offer') and digits and kind not in ('repeat_request', 'silence', 'angry', 'out_of_scope'):
        if resolve_card(S, O, V, said, digits, prefix, True):
            return
    common = common_kinds(S, O, kind, side, prefix)
    if common:
        return
    if stage == 'oos':
        if kind == 'yes':
            finish(O, S_MENU_A, 'end_menu')
            return
        if kind == 'no':
            back = S.get('oos_back') or 'open'
            q = S.get('oos_q') or ''
            S['stage'] = back
            S['q'] = q
            S['tries'] = 0
            S['silences'] = 0
            O['say'] = (prefix + ' ' + q).strip()
            O['route'] = 'talk_' + back
            S['last_say'] = O['say']
            return
        try_fail(S, O, prefix, '')
        return
    if kind == 'out_of_scope':
        S['oos_back'] = stage
        S['oos_q'] = S.get('q') or ''
        ask(S, O, 'oos', S_OOS, 'Sizi ana menüye aktarmamı ister misiniz?', prefix)
        return
    if stage == 'open':
        try_fail(S, O, prefix, 'Kredi kartı ekstre borcunuzla ilgili size nasıl yardımcı olabilirim?')
        return
    if stage == 'card':
        if kind in ('card_named', 'yes') or said or digits:
            if resolve_card(S, O, V, said, digits, prefix, True):
                return
        if kind == 'all_cards':
            try_fail(S, O, (prefix + ' Borç bilgisini kart kart verebiliyorum.').strip(), select_question(S['cards'], unread(S)))
            return
        if kind == 'no_card_at_hand' and S.get('sub'):
            try_fail(S, O, prefix, '')
            return
        try_fail(S, O, prefix, '')
        return
    if stage == 'another':
        if said or digits:
            if resolve_card(S, O, V, said, digits, prefix, True):
                return
        if kind == 'yes':
            left = unread(S)
            if len(left) == 1:
                start_read(S, O, V, left[0], prefix)
                return
            ask(S, O, 'card', select_question(S['cards'], left), 'Hangi kartınızın borcunu öğrenmek istersiniz?', prefix)
            return
        if kind in ('no', 'nothing'):
            if not S.get('any_debt'):
                finish(O, S_MENU, 'end_menu')
                return
            offer_entry(S, O, V, prefix)
            return
        try_fail(S, O, prefix, '')
        return
    if stage == 'offer':
        if kind == 'email':
            email_entry(S, O, V, prefix)
            return
        if kind == 'past_statement':
            if not S.get('email'):
                email_entry(S, O, V, prefix)
                return
            S['esub'] = 'latest'
            q = 'Son ekstrenizi göndermemi ister misiniz?'
            ask(S, O, 'email', q, q, (prefix + ' Yalnızca son kesilen ekstrenizi gönderebiliyorum.').strip())
            return
        if kind == 'other_address':
            if not S.get('email'):
                email_entry(S, O, V, prefix)
                return
            email_entry(S, O, V, (prefix + ' Ekstrenizi yalnızca bankamızda kayıtlı e-posta adresinize gönderebiliyorum.').strip())
            return
        if kind == 'paper':
            finish(O, 'Kağıt ekstre ve kısa mesaj bu adımda yapabildiğim işlemler değil. ' + S_MENU, 'end_menu')
            return
        if kind == 'week':
            pw = parse_week(wsaid)
            week_entry(S, O, V, prefix, pw if pw > 0 else 0)
            return
        if kind == 'nothing' or kind == 'no':
