import json, re, datetime

ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
DIGW = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
MONTHS = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
CUR_NAME = dict(TL='Türk Lirası', USD='Dolar', EUR='Euro', GBP='İngiliz Sterlini')
CUR_ORDER = ['TL', 'USD', 'EUR', 'GBP']
ORD = ['', 'birinci', 'ikinci', 'üçüncü', 'dördüncü']


def tr_lower(s):
    return str(s or '').replace('İ', 'i').replace('I', 'ı').lower()


def fold(s):
    t = tr_lower(s)
    for a, b in (('ı', 'i'), ('ğ', 'g'), ('ü', 'u'), ('ş', 's'), ('ö', 'o'), ('ç', 'c'), ('â', 'a'), ('î', 'i'), ('û', 'u')):
        t = t.replace(a, b)
    return t


def three(n):
    h = n // 100
    r = n % 100
    out = []
    if h:
        out.append('yüz' if h == 1 else ONES[h] + ' yüz')
    if r // 10:
        out.append(TENS[r // 10])
    if r % 10:
        out.append(ONES[r % 10])
    return ' '.join(out)


def int_words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    parts = []
    for size, word in ((10 ** 9, 'milyar'), (10 ** 6, 'milyon'), (1000, 'bin')):
        q = n // size
        n = n % size
        if q:
            if size == 1000 and q == 1:
                parts.append('bin')
            else:
                parts.append(three(q) + ' ' + word)
    if n:
        parts.append(three(n))
    return ' '.join(parts)


def to_num(x):
    try:
        if x is None or str(x).strip() in ('', 'null', 'None'):
            return None
        return float(str(x).strip())
    except Exception:
        return None


def money(amount, cur):
    v = to_num(amount)
    if v is None:
        return ''
    c = int(round(abs(v) * 100))
    main = c // 100
    sub = c % 100
    if cur == 'TL':
        if sub == 0:
            return int_words(main) + ' Türk Lirası'
        if main == 0:
            return int_words(sub) + ' kuruş'
        return int_words(main) + ' lira ' + int_words(sub) + ' kuruş'
    unit = dict(USD='dolar', EUR='Euro', GBP='İngiliz Sterlini')[cur]
    small = 'peni' if cur == 'GBP' else 'sent'
    if sub == 0:
        return int_words(main) + ' ' + unit
    return int_words(main) + ' ' + unit + ' ' + int_words(sub) + ' ' + small


def parse_ddmmyyyy(s):
    try:
        m = re.match(r'^\s*(\d{1,2})\.(\d{1,2})\.(\d{4})\s*$', str(s or ''))
        if not m:
            return None
        return datetime.date(int(m.group(3)), int(m.group(2)), int(m.group(1)))
    except Exception:
        return None


def date_tr(s):
    d = parse_ddmmyyyy(s)
    if d is None:
        return ''
    return str(d.day) + ' ' + MONTHS[d.month - 1] + ' ' + str(d.year)


def today_of(now):
    s = str(now or '').strip()
    try:
        return datetime.date.fromisoformat(s[:10])
    except Exception:
        return datetime.date(2026, 10, 12)


def digits_tr(d):
    return ' '.join(DIGW[int(ch)] for ch in str(d) if ch.isdigit())


def suffix_for_word(w):
    vowels = [ch for ch in w if ch in 'aeıioöuü']
    v = vowels[-1] if vowels else 'e'
    hv = dict(a='ı', ı='ı', e='i', i='i', o='u', u='u', ö='ü', ü='ü')[v]
    cons = 't' if w[-1] in 'fstkçşhp' else 'd'
    return "'" + cons + hv + 'r'


def year_last_word(y):
    y = int(y)
    if y % 10:
        return ONES[y % 10]
    if y % 100:
        return TENS[(y % 100) // 10]
    if y % 1000:
        return 'yüz'
    return 'bin'


def due_sentence(due_s, today):
    d = parse_ddmmyyyy(due_s)
    if d is None:
        return ''
    if d == today:
        return 'Borçlarınız için son ödeme tarihiniz bugündür.'
    return 'Borçlarınız için son ödeme tarihiniz ' + date_tr(due_s) + suffix_for_word(year_last_word(d.year)) + '.'


def tl_case(b):
    rd = to_num(b.get('remainingDebt')) or 0.0
    rm = to_num(b.get('remainingMinPayment')) or 0.0
    mp = to_num(b.get('minPayment')) or 0.0
    if rd <= 0:
        return 'no_debt'
    if rm > 0 and rm >= mp:
        return 'none_paid'
    if rm <= 0:
        return 'min_paid'
    return 'below_min'


def block_present(b):
    return isinstance(b, dict) and len(b) > 0


def block_clear(b):
    v = to_num(b.get('remainingDebt'))
    return v is None or v <= 0


def join_names(names):
    if not names:
        return ''
    if len(names) == 1:
        return names[0]
    return ', '.join(names[:-1]) + ' ve ' + names[-1]


def no_debt_sentence(codes):
    names = [CUR_NAME[c] for c in CUR_ORDER if c in codes]
    if not names:
        return ''
    return join_names(names) + ' borcunuz bulunmamaktadır.'


def spoken_name(name):
    n = str(name or '').strip()
    low = tr_lower(n)
    if not n or len(n) > 40:
        return ''
    for bad in ('talimat', 'yok say', 'numara', 'oku', 'ignore', 'instruction'):
        if bad in low:
            return ''
    return n


def card_intro(card):
    nm = spoken_name(card.get('name'))
    base = 'Sonu ' + digits_tr(card.get('l4')) + ' ile biten '
    return base + (nm + ' ' if nm else '')


def phase_of(bal, today):
    sd = parse_ddmmyyyy(bal.get('statementDate'))
    nsd = parse_ddmmyyyy(bal.get('nextStatementDate'))
    due = parse_ddmmyyyy(bal.get('lastPayDate'))
    if sd is None:
        return 'no_statement'
    if today == sd or (nsd is not None and today == nsd):
        return 'cut_day'
    if due is not None and today > due:
        return 'after_due'
    return 'normal'


def reading(card, bal, today, focus):
    """returns (text, kind) kind: debt | nodebt"""
    intro = card_intro(card)
    ph = phase_of(bal, today)
    blocks = []
    for c in CUR_ORDER:
        b = bal.get('debt' + c)
        if block_present(b):
            blocks.append((c, b))
    if ph == 'no_statement':
        t = intro + 'kartınızın henüz kesilmiş bir ekstresi olmadığı için ekstre borcunuz bulunmamaktadır.'
        nd = date_tr(bal.get('nextStatementDate'))
        if nd:
            t = t + ' İlk hesap kesim tarihiniz ' + nd + ' olacak.'
        return t, 'nodebt'
    if ph in ('cut_day', 'after_due'):
        parts = []
        if ph == 'cut_day':
            parts.append('Hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek.')
            parts.append(intro + 'kartınıza ait toplam borç bilgileriniz şöyle:')
        else:
            parts.append(intro + 'kartınızın son ödeme tarihi ' + date_tr(bal.get('lastPayDate')) + ' idi, bu tarih geçti.')
        clear = []
        owed = 0
        for c, b in blocks:
            tv = to_num(b.get('totalDebt'))
            if tv is not None and tv > 0:
                parts.append(CUR_NAME[c] + ' cinsinden toplam borcunuz ' + money(tv, c) + '.')
                owed += 1
            else:
                clear.append(c)
        if owed:
            s = no_debt_sentence(clear)
            if s:
                parts.append(s)
        else:
            parts.append('Toplam borcunuz bulunmamaktadır.')
        ap = auto_payment_sentence(bal, today)
        if ap:
            parts.append(ap)
        return ' '.join(parts), ('debt' if owed else 'nodebt')
    owed = [(c, b) for c, b in blocks if not block_clear(b)]
    if str(bal.get('statementPaymentStatus') or '') == 'NO_DEBT' or not owed:
        nm = spoken_name(card.get('name'))
        t = 'Sonu ' + digits_tr(card.get('l4')) + ' ile biten ' + (nm + ' ' if nm else '') + 'kartınızın ' + date_tr(bal.get('statementDate')) + ' tarihli ekstresinden borcunuz bulunmamaktadır.'
        tlb = bal.get('debtTL') if block_present(bal.get('debtTL')) else dict()
        g = to_num(tlb.get('totalDebt'))
        if g is not None and g > 0:
            t = t + ' Gelecek dönemler dahil toplam borcunuz ' + money(g, 'TL') + '.'
        due = parse_ddmmyyyy(bal.get('lastPayDate'))
        dd = bal.get('lastPayDate') if (due is not None and due >= today) else bal.get('nextLastPayDate')
        if date_tr(dd):
            t = t + ' Son ödeme tarihiniz ' + date_tr(dd) + ' olacaktır.'
        return t, 'nodebt'
    head = intro + 'kartınıza ait ' + date_tr(bal.get('statementDate')) + ' tarihinde kesilen ekstre '
    if focus == 'due_only':
        return intro + 'kartınız için: ' + due_sentence(bal.get('lastPayDate'), today), 'debt'
    parts = []
    first = True
    for c, b in blocks:
        if c != 'TL':
            ta = to_num(b.get('transferAmount'))
            if ta is not None and ta > 0:
                parts.append(CUR_NAME[c] + ' borcunuzun bir kısmı Türk Lirası borcunuza aktarılmıştır.')
    for c, b in owed:
        X = money(b.get('statementDebt'), c)
        Z = money(b.get('minPayment'), c)
        Y = money(b.get('remainingDebt'), c)
        T = money(b.get('remainingMinPayment'), c)
        if c == 'TL':
            k = tl_case(b)
            if focus == 'min_only':
                if k == 'min_paid':
                    s = 'Türk Lirası borcunuz için minimum ödemenizi yaptığınız için teşekkür ederiz.'
                elif k == 'below_min':
                    s = 'Türk Lirası borcunuz için ödenmesi gereken minimum tutar ' + Z + ', kalan minimum ödeme tutarınız ' + T + '.'
                else:
                    s = 'Türk Lirası borcunuz için ödenmesi gereken minimum tutar ' + Z + '.'
            elif k == 'none_paid':
                s = 'Türk Lirası borcunuz ' + X + ', ödenmesi gereken minimum tutar ' + Z + '.'
            elif k == 'min_paid':
                s = 'Türk Lirası borcunuz ' + X + ', kalan toplam borcunuz ' + Y + '. Minimum ödemenizi yaptığınız için teşekkür ederiz.'
            else:
                s = 'Türk Lirası borcunuz ' + X + ', ödenmesi gereken minimum tutar ' + Z + ', kalan toplam borcunuz ' + Y + ', kalan minimum ödeme tutarınız ' + T + '.'
        else:
            if focus == 'min_only':
                s = CUR_NAME[c] + ' borcunuz için ödenmesi gereken minimum tutar ' + Z + '.'
            else:
                s = CUR_NAME[c] + ' borcunuz ' + X + ', kalan toplam borcunuz ' + Y + ', ödenmesi gereken minimum tutar ' + Z + '.'
        if first:
            s = head + s
            first = False
        parts.append(s)
    if focus != 'min_only':
        nd = no_debt_sentence([c for c, b in blocks if block_clear(b)])
        if nd:
            parts.append(nd)
    ap = auto_payment_sentence(bal, today)
    if ap:
        parts.append(ap)
    ds = due_sentence(bal.get('lastPayDate'), today)
    if ds:
        parts.append(ds)
    return ' '.join(parts), 'debt'


def auto_payment_sentence(bal, today):
    due = parse_ddmmyyyy(bal.get('lastPayDate'))
    if due is None or not today > due or str(bal.get('automaticPaymentFlag') or '') != 'Y':
        return ''
    tlb = bal.get('debtTL') if block_present(bal.get('debtTL')) else dict()
    v = to_num(tlb.get('remainAutomaticPaymentAmount'))
    if v is None or v <= 0:
        return ''
    return 'Kalan otomatik ödeme tutarınız ' + money(v, 'TL') + '.'


NUMW = dict(sifir=0, bir=1, iki=2, uc=3, dort=4, bes=5, alti=6, yedi=7, sekiz=8, dokuz=9)
TENW = dict(on=10, yirmi=20, otuz=30, kirk=40, elli=50, altmis=60, yetmis=70, seksen=80, doksan=90)


def words_to_digits(s):
    """'dört iki beş üç' -> '4253', 'kırk iki elli üç' -> '4253', '42 53' -> '4253'"""
    t = fold(s)
    t = re.sub(r'[^a-z0-9 ]', ' ', t)
    out = ''
    cur = None
    state = ''
    for tok in t.split():
        if tok.isdigit():
            if cur is not None:
                out += str(cur)
                cur = None
            out += tok
            state = ''
            continue
        if tok in TENW:
            if cur is not None:
                out += str(cur)
            cur = TENW[tok]
            state = 'ten'
        elif tok in NUMW:
            v = NUMW[tok]
            if cur is not None and state in ('ten', 'hundred') and v > 0:
                cur = cur + v
                out += str(cur)
                cur = None
                state = ''
            elif cur is not None and state in ('ten', 'hundred'):
                out += str(cur)
                cur = None
                out += str(v)
                state = ''
            else:
                if cur is not None:
                    out += str(cur)
                    cur = None
                cur = v
                state = 'one'
        elif tok == 'yuz':
            base = cur if (cur is not None and state == 'one') else 1
            cur = base * 100
            state = 'hundred'
        elif tok == 'bin':
            base = cur if cur is not None else 1
            cur = None
            out += str(base)
            state = 'thousand'
        else:
            continue
    if cur is not None:
        out += str(cur)
    return out


def parse_week(s):
    t = fold(s).strip()
    if not t:
        return 0
    m = re.search(r'\d+', t)
    if m:
        v = int(m.group(0))
        return v if 1 <= v <= 4 else -1
    for w, v in (('birinci', 1), ('ilk', 1), ('ikinci', 2), ('ucuncu', 3), ('dorduncu', 4), ('son', 4), ('dort', 4), ('uc', 3), ('iki', 2), ('bir', 1)):
        if re.search(r'\b' + w + r'\b', t):
            return v
    return 0


STOP = set(['kart', 'karti', 'kartim', 'kartimin', 'kartimi', 'kartimla', 'kartinin', 'kartlarim', 'kredi', 'borcu', 'borcunu', 'borcum', 'borcumu', 'olan',
            'benim', 'adli', 'isimli', 'bu', 've', 'de', 'da', 'ile', 'icin', 'ogrenmek', 'istiyorum', 'lutfen', 'sey', 'hani', 'su', 'o', 'mi', 'diger', 'evet'])


def name_tokens(s):
    return [w for w in re.sub(r'[^a-z0-9 ]', ' ', fold(s)).split() if w and w not in STOP]


def tok_match(a, b):
    if a == b:
        return True
    if len(a) >= 3 and len(b) >= 3 and (a.startswith(b) or b.startswith(a)):
        return True
    return False


def match_name(said, cards):
    st = [w for w in name_tokens(said) if not w.isdigit()]
    if not st:
        return []
    core = [w for w in st if w != 'yildiz']
    exact = []
    partial = []
    for i, c in enumerate(cards):
        nt = name_tokens(c.get('name'))
        if not nt:
            continue
        ncore = [w for w in nt if w != 'yildiz']
        if not core:
            if 'yildiz' in nt:
                partial.append(i)
            continue
        all_said = all(any(tok_match(s, n) for n in nt) for s in core)
        all_name = all(any(tok_match(s, n) for s in core) for n in ncore)
        if all_said and all_name:
            exact.append(i)
        elif all_said:
            partial.append(i)
    return exact if exact else partial


def mask_match(said, masked):
    """said digits vs the masked number aligned at the end; '*' is unknown"""
    m = str(masked or '')
    if len(said) > len(m):
        return False
    tail = m[len(m) - len(said):]
    for a, b in zip(said, tail):
        if b.isdigit() and a != b:
            return False
    return True


def match_digits(d, cards, cand):
    pool = cand if cand else list(range(len(cards)))
    if len(d) == 16:
        return [i for i in pool if mask_match(d, cards[i].get('num'))]
    return [i for i in pool if mask_match(d, cards[i].get('num')) and str(cards[i].get('l4')) == d[-4:]]


def distinct(seq):
    out = []
    for x in seq:
        if x and x not in out:
            out.append(x)
    return out


def select_question(cards, prefer):
    pool = [i for i in prefer if cards[i].get('main')] or [i for i in range(len(cards)) if cards[i].get('main')]
    names = distinct([spoken_name(cards[i].get('name')) for i in pool])[:2]
    q = 'Hangi kartınızın borcunu öğrenmek istersiniz?'
    if len(names) == 2:
        q = q + ' Örneğin, ' + names[0] + ' veya ' + names[1] + ' diyebilirsiniz.'
    elif len(names) == 1:
        q = q + ' Örneğin, ' + names[0] + ' diyebilirsiniz.'
    return q


def email_spoken(addr):
    a = str(addr or '').strip()
    if '@' not in a:
        return ''
    local, dom = a.split('@', 1)
    if re.match(r'^[a-z]+(\.[a-z]+)?$', local) and len(local) <= 20:
        return a + ' adresine'
    label = dom.split('.')[0]
    return local[0] + ' ile başlayan ' + label + ' adresinize'


