def read_tree(V, prefix):
    out = dict()
    obj = V.get(prefix)
    if isinstance(obj, str) and obj.strip().startswith('{'):
        try:
            obj = json.loads(obj)
        except Exception:
            obj = None
    if isinstance(obj, dict):
        d = obj.get('data')
        if isinstance(d, dict):
            return d
    p = prefix + '.data.'
    for k in list(V.keys()):
        ks = str(k)
        if not ks.startswith(p):
            continue
        parts = ks[len(p):].split('.')
        cur = out
        for part in parts[:-1]:
            if not isinstance(cur.get(part), dict):
                cur[part] = dict()
            cur = cur[part]
        cur[parts[-1]] = V.get(k)
    return out


def call_ok(body, status):
    rc = str(((body.get('result') or dict()).get('returnCode')) if isinstance(body.get('result'), dict) else '')
    st = str(status if status is not None else '200')
    return rc == '1' and st.startswith('2')


def list_cards(body):
    d = body.get('data') if isinstance(body.get('data'), dict) else dict()
    cs = d.get('cards')
    items = []
    if isinstance(cs, list):
        items = cs
    elif isinstance(cs, dict):
        i = 0
        while str(i) in cs:
            items.append(cs[str(i)])
            i += 1
    out = []
    for c in items:
        if not isinstance(c, dict):
            continue
        num = str(c.get('cardNumber') or '')
        l4 = str(c.get('cardNumberLast4') or num[-4:])
        out.append(dict(num=num, l4=l4, name=str(c.get('productName') or ''), main=str(c.get('isMainCard')).lower() != 'false'))
    return out


def has_email(body):
