def ask(S, O, stage, q, short, prefix):
    if S.get('stage') != stage or S.get('q') != q:
        S['tries'] = 0
        S['silences'] = 0
        S['broken'] = 0
        S['chat'] = 0
    S['stage'] = stage
    S['q'] = q
    S['short'] = short or q
    say = (prefix + ' ' + q).strip()
    O['say'] = say
    O['route'] = 'talk_' + stage
    S['last_say'] = say


def finish(O, text, route):
    O['final'] = text.strip()
    O['route'] = route


def try_fail(S, O, prefix, again):
    S['tries'] = int(S.get('tries') or 0) + 1
    if S['tries'] >= TRIES:
        finish(O, S_FAIL3, 'end_menu')
        return
    q = again or S.get('q') or ''
    O['say'] = (prefix + ' ' + q).strip()
    O['route'] = 'talk_' + S.get('stage')
    S['last_say'] = O['say']


def reask(S, O, prefix):
    O['say'] = (prefix + ' ' + (S.get('q') or '')).strip()
    O['route'] = 'talk_' + S.get('stage')


def main_cards(S):
    return [i for i, c in enumerate(S.get('cards') or []) if c.get('main')]


def unread(S):
    return [i for i in main_cards(S) if i not in (S.get('read') or [])]


def start_read(S, O, V, idx, prefix):
    cards = S['cards']
    S['cur'] = idx
    S['cand'] = []
    S['sub'] = ''
    S['dbuf'] = ''
    O['cur_card'] = cards[idx]['num']
    O['route'] = 'bal_' + str(min(idx, BAL_NODES - 1))
    S['pend'] = 'bal'
    S['read_prefix'] = prefix
    left = [i for i in unread(S) if i != idx]
    if not S.get('email_known') and S.get('after_read', '') in ('', 'email') and (not left or S.get('focus') or S.get('after_read') == 'email'):
        O['need_email'] = 'yes'


def choose(S, O, V, idx, prefix):
    cards = S['cards']
    if not cards[idx].get('main'):
        S['cand'] = []
        S['sub'] = ''
        ask(S, O, 'card', select_question(cards, unread(S)), 'Hangi kartınızın borcunu öğrenmek istersiniz?',
            prefix + ' Bu kart için ekstre borcu sorgulanabilecek uygun bir kart bulunmuyor. Lütfen başka bir kartınızı seçin.')
        return
    start_read(S, O, V, idx, prefix)


def resolve_card(S, O, V, said, digits, prefix, costs):
    """returns True when it produced output"""
    cards = S.get('cards') or []
    d = re.sub(r'\D', '', words_to_digits(digits or '')) if digits else ''
    if not d and said:
        d2 = re.sub(r'\D', '', words_to_digits(said))
        if len(d2) >= 4:
            d = d2
    sub = S.get('sub') or ''
    if d:
        need = 16 if sub == 'd16' else (6 if sub == 'd6' else 4)
        buf = (S.get('dbuf') or '') + d
        if len(d) in (4, 6, 16) and len(buf) != need:
            buf = d
        if len(buf) < need and len(buf) not in (4, 6):
            S['dbuf'] = buf
            O['say'] = (prefix + ' Lütfen kalan haneleri de söyler misiniz?').strip()
            O['route'] = 'talk_' + (S.get('stage') or 'card')
            return True
        if len(buf) > 16 or (len(buf) > 6 and len(buf) < 16 and sub == 'd16'):
            if len(buf) < 16:
                S['dbuf'] = buf
                reask(S, O, prefix + ' Lütfen hanelerin tamamını söyler misiniz?')
                return True
        S['dbuf'] = ''
        if len(buf) > 16:
            buf = buf[-16:]
        if len(buf) not in (4, 6, 16):
            buf = buf[-4:] if len(buf) < 6 else buf[-6:]
        hits = match_digits(buf, cards, S.get('cand') or [])
        if not hits and S.get('cand'):
            hits = match_digits(buf, cards, [])
            if hits:
                S['cand'] = []
                S['sub'] = ''
        if len(hits) == 1:
            choose(S, O, V, hits[0], prefix)
            return True
        if len(hits) > 1:
            S['cand'] = hits
            if len(buf) == 4:
                S['sub'] = 'd6'
                ask(S, O, 'card', 'Son dört hanesi ' + digits_tr(buf) + ' olan birden fazla kartınız var. Kartınızın son altı hanesini söyler misiniz?', 'Kartınızın son altı hanesini söyler misiniz?', prefix)
            else:
                S['sub'] = 'd16'
                ask(S, O, 'card', 'Son altı hanesi aynı olan birden fazla kartınız var. Kart numaranızı söyler misiniz?', 'Kart numaranızı söyler misiniz?', prefix)
            return True
        S['tries'] = int(S.get('tries') or 0) + 1
        if S['tries'] >= TRIES:
            finish(O, S_FAIL3, 'end_menu')
            return True
        if S.get('stage') != 'card':
            S['stage'] = 'card'
            S['q'] = select_question(cards, unread(S))
            S['short'] = 'Hangi kartınızın borcunu öğrenmek istersiniz?'
        reask(S, O, prefix + ' Söylediğiniz numarayla eşleşen bir kartınız bulunmuyor.')
        return True
    if said:
        hits = match_name(said, cards)
        if S.get('cand') and hits:
            inter = [i for i in hits if i in S['cand']]
            hits = inter or hits
        if len(hits) == 1:
            choose(S, O, V, hits[0], prefix)
            return True
        if len(hits) > 1:
            names = distinct([cards[i].get('name') for i in hits])
            S['cand'] = hits
            if len(names) == 1:
                S['sub'] = 'd4'
                nm = spoken_name(names[0]) or 'Bu'
                ask(S, O, 'card', nm + ' isimli birden fazla kartınız var. Kartınızın son dört hanesini söyler misiniz?', 'Kartınızın son dört hanesini söyler misiniz?', prefix)
            else:
                S['sub'] = ''
                sp = distinct([spoken_name(n) for n in names])
                ask(S, O, 'card', 'Bu isimle eşleşen ' + join_names(sp) + ' kartlarınız var. Hangisinin borcunu öğrenmek istersiniz?', 'Hangi kartınızın borcunu öğrenmek istersiniz?', prefix)
            return True
        S['cand'] = []
        S['sub'] = ''
        names = distinct([spoken_name(cards[i].get('name')) for i in main_cards(S)])
        q = 'Kartlarınız şunlar: ' + join_names(names) + '. Hangi kartınızın borcunu öğrenmek istersiniz?' if names else select_question(cards, unread(S))
        if S.get('stage') != 'card':
            ask(S, O, 'card', q, 'Hangi kartınızın borcunu öğrenmek istersiniz?', prefix + ' Bu isimde bir kartınız bulunmuyor.')
            if costs:
                S['tries'] = 1
            return True
        S['q'] = q
        try_fail(S, O, prefix + ' Bu isimde bir kartınız bulunmuyor.', q)
        return True
    return False


