        st = V.get('api_list_status_code', V.get('api_list_response.status_code'))
        rc = str((body.get('result') or dict()).get('returnCode') or '') if isinstance(body.get('result'), dict) else ''
        S['listed'] = 1
        if rc == 'FB_IVR_CHANNEL_102' or str(st) == '404':
            finish(O, S_NOCARD, 'end_menu')
            return
        if not call_ok(body, st):
            finish(O, S_SVC, 'end_agent')
            return
        S['cards'] = list_cards(body)
        if not main_cards(S):
            finish(O, S_NOCARD, 'end_menu')
            return
        handle_bank_list_again(S, O, V, today)
        return
