        S['cur_sd'] = str(bal.get('statementDate') or '')
        if S['cur_sd'] in ('null', 'None'):
            S['cur_sd'] = ''
        text, kind = reading(S['cards'][idx], bal, today, S.get('focus') or '')
        text = ((S.get('read_prefix') or '') + ' ' + text).strip()
        rd = S.get('read') or []
        if idx not in rd:
            rd.append(idx)
        S['read'] = rd
        after_reading(S, O, V, text, kind)
        return
    if pend == 'email':
        cont = S.get('cont') or 'offer'
        prefix = S.get('stash') or ''
        if cont == 'offer':
            offer_entry(S, O, V, prefix)
