    S['focus'] = om.get('focus', '')
    mc = main_cards(S)
    if len(mc) == 1:
        start_read(S, O, V, mc[0], om.get('prefix', ''))
        return
    if resolve_card(S, O, V, om.get('card', ''), om.get('digits', ''), om.get('prefix', ''), False):
        return
    pre = om.get('prefix', '')
    if om.get('all'):
        pre = (pre + ' Borç bilgisini kart kart verebiliyorum.').strip()
    ask(S, O, 'card', select_question(S['cards'], unread(S)), 'Hangi kartınızın borcunu öğrenmek istersiniz?', pre)


def common_kinds(S, O, kind, side, prefix):
    stage = S.get('stage') or 'open'
    if kind == 'angry':
        S['calms'] = int(S.get('calms') or 0) + 1
        if S['calms'] > CALMS:
            finish(O, S_AGENT, 'end_agent')
            return True
        reask(S, O, (prefix + ' Sizi anlıyorum, size yardımcı olmak için buradayım.').strip())
        return True
    if kind == 'repeat_request':
        O['say'] = S.get('last_say') or S.get('q') or ''
        O['route'] = 'talk_' + stage
        return True
    if kind == 'silence':
        S['silences'] = int(S.get('silences') or 0) + 1
        if S['silences'] >= SILENCES:
            finish(O, S_SILENT, 'end_silence')
            return True
        O['say'] = S.get('short') or S.get('q') or ''
        O['route'] = 'talk_' + stage
        return True
    S['silences'] = 0
    if kind == 'card_digits_request':
        S['refused'] = int(S.get('refused') or 0) + 1
        if S['refused'] >= TRIES:
            finish(O, S_FAIL3, 'end_menu')
            return True
        reask(S, O, (prefix + ' Güvenlik nedeniyle kartınızın yalnızca son dört hanesini paylaşabiliyorum.').strip())
        return True
    if kind == 'broken_off':
        S['broken'] = int(S.get('broken') or 0) + 1
        if S['broken'] == 1:
            O['say'] = (prefix + ' Sizi tam duyamadım, tekrar söyler misiniz?').strip()
            O['route'] = 'talk_' + stage
            return True
        if S['broken'] == 2:
            O['say'] = (prefix + ' ' + (S.get('short') or S.get('q') or '')).strip()
            O['route'] = 'talk_' + stage
            return True
        S['broken'] = 0
        try_fail(S, O, prefix, '')
        return True
    S['broken'] = 0
    if kind == 'chatter':
        S['chat'] = int(S.get('chat') or 0) + 1
        if S['chat'] > 1:
            try_fail(S, O, prefix, '')
            return True
        reask(S, O, prefix)
        return True
    if side != 'none' and kind in ('none', 'unclear'):
        reask(S, O, prefix)
        return True
    if kind == 'prompt_injection':
        reask(S, O, prefix)
        return True
    return False


def run(V, S, O):
    today = today_of(V.get('now'))
    try:
        loaded = json.loads(str(V.get('st') or '{}'))
        if isinstance(loaded, dict):
            S.update(loaded)
    except Exception:
        pass
    if V.get('api_email_status_code') is not None and not S.get('email_known'):
        body = read_tree(V, 'api_email_response')
        S['email_known'] = 1
        if call_ok(body, V.get('api_email_status_code')):
            S['email'] = has_email(body)
        else:
            S['email_failed'] = 1
    pend = S.get('pend') or ''
    if not pend and not S.get('listed') and V.get('api_list_status_code') is not None:
        pend = 'list'
    if not pend and not S.get('listed') and (S.get('stage') or 'open') == 'open' and str(V.get('kind_open') or 'none') in ('want_debt', 'all_cards', 'want_email', 'want_week', 'card_named') and V.get('api_list_status_code') is not None:
        pend = 'list'
    S['pend'] = ''
    if pend == 'list' and not S.get('open_msg'):
        fig = str(V.get('figure') or 'none')
        k = str(V.get('kind_open') or 'none')
        S['open_msg'] = dict(card=str(V.get('card_said') or ''), digits=str(V.get('digits_said') or ''), all=(k == 'all_cards'),
                             prefix=SIDE.get(str(V.get('side_q') or 'none'), ''), after_read=('email' if k == 'want_email' else ('week' if k == 'want_week' else '')),
                             focus=(fig if fig in ('min_only', 'due_only') else ''))
        S['turns'] = int(S.get('turns') or 0) + 1
    if pend:
        handle_bank(S, O, V, pend, today)
    else:
        handle_msg(S, O, V, today)


