import json, re, datetime

ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
DIGW = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
MONTHS = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
CUR_NAME = dict(TL='Türk Lirası', USD='Dolar', EUR='Euro', GBP='İngiliz Sterlini')
CUR_ORDER = ['TL', 'USD', 'EUR', 'GBP']
ORD = ['', 'birinci', 'ikinci', 'üçüncü', 'dördüncü']


def tr_lower(s):
    return str(s or '').replace('İ', 'i').replace('I', 'ı').lower()


def fold(s):
    t = tr_lower(s)
    for a, b in (('ı', 'i'), ('ğ', 'g'), ('ü', 'u'), ('ş', 's'), ('ö', 'o'), ('ç', 'c'), ('â', 'a'), ('î', 'i'), ('û', 'u')):
        t = t.replace(a, b)
    return t


def three(n):
    h = n // 100
    r = n % 100
    out = []
    if h:
        out.append('yüz' if h == 1 else ONES[h] + ' yüz')
    if r // 10:
        out.append(TENS[r // 10])
    if r % 10:
        out.append(ONES[r % 10])
    return ' '.join(out)


def int_words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    parts = []
    for size, word in ((10 ** 9, 'milyar'), (10 ** 6, 'milyon'), (1000, 'bin')):
        q = n // size
        n = n % size
        if q:
            if size == 1000 and q == 1:
                parts.append('bin')
            else:
                parts.append(three(q) + ' ' + word)
    if n:
        parts.append(three(n))
    return ' '.join(parts)


def to_num(x):
    try:
        if x is None or str(x).strip() in ('', 'null', 'None'):
            return None
        return float(str(x).strip())
    except Exception:
        return None


def money(amount, cur):
    v = to_num(amount)
    if v is None:
        return ''
    c = int(round(abs(v) * 100))
    main = c // 100
    sub = c % 100
    if cur == 'TL':
        if sub == 0:
            return int_words(main) + ' Türk Lirası'
        if main == 0:
            return int_words(sub) + ' kuruş'
        return int_words(main) + ' lira ' + int_words(sub) + ' kuruş'
    unit = dict(USD='dolar', EUR='Euro', GBP='İngiliz Sterlini')[cur]
    small = 'peni' if cur == 'GBP' else 'sent'
    if sub == 0:
        return int_words(main) + ' ' + unit
    return int_words(main) + ' ' + unit + ' ' + int_words(sub) + ' ' + small


def parse_ddmmyyyy(s):
    try:
        m = re.match(r'^\s*(\d{1,2})\.(\d{1,2})\.(\d{4})\s*$', str(s or ''))
        if not m:
            return None
        return datetime.date(int(m.group(3)), int(m.group(2)), int(m.group(1)))
    except Exception:
        return None


def date_tr(s):
    d = parse_ddmmyyyy(s)
    if d is None:
        return ''
    return str(d.day) + ' ' + MONTHS[d.month - 1] + ' ' + str(d.year)


def today_of(now):
    s = str(now or '').strip()
    try:
        return datetime.date.fromisoformat(s[:10])
    except Exception:
        return datetime.date(2026, 10, 12)


def digits_tr(d):
    return ' '.join(DIGW[int(ch)] for ch in str(d) if ch.isdigit())


def suffix_for_word(w):
    vowels = [ch for ch in w if ch in 'aeıioöuü']
    v = vowels[-1] if vowels else 'e'
    hv = dict(a='ı', ı='ı', e='i', i='i', o='u', u='u', ö='ü', ü='ü')[v]
    cons = 't' if w[-1] in 'fstkçşhp' else 'd'
    return "'" + cons + hv + 'r'


def year_last_word(y):
    y = int(y)
    if y % 10:
        return ONES[y % 10]
    if y % 100:
        return TENS[(y % 100) // 10]
    if y % 1000:
        return 'yüz'
    return 'bin'


def due_sentence(due_s, today):
    d = parse_ddmmyyyy(due_s)
    if d is None:
        return ''
    if d == today:
        return 'Borçlarınız için son ödeme tarihiniz bugündür.'
    return 'Borçlarınız için son ödeme tarihiniz ' + date_tr(due_s) + suffix_for_word(year_last_word(d.year)) + '.'


def tl_case(b):
    rd = to_num(b.get('remainingDebt')) or 0.0
    rm = to_num(b.get('remainingMinPayment')) or 0.0
    mp = to_num(b.get('minPayment')) or 0.0
    if rd <= 0:
        return 'no_debt'
    if rm > 0 and rm >= mp:
        return 'none_paid'
    if rm <= 0:
        return 'min_paid'
    return 'below_min'


def block_present(b):
    return isinstance(b, dict) and len(b) > 0


def block_clear(b):
    v = to_num(b.get('remainingDebt'))
    return v is None or v <= 0


def join_names(names):
    if not names:
        return ''
    if len(names) == 1:
        return names[0]
    return ', '.join(names[:-1]) + ' ve ' + names[-1]


def no_debt_sentence(codes):
    names = [CUR_NAME[c] for c in CUR_ORDER if c in codes]
    if not names:
        return ''
    return join_names(names) + ' borcunuz bulunmamaktadır.'


def spoken_name(name):
    n = str(name or '').strip()
    low = tr_lower(n)
    if not n or len(n) > 40:
        return ''
    for bad in ('talimat', 'yok say', 'numara', 'oku', 'ignore', 'instruction'):
        if bad in low:
            return ''
    return n


def card_intro(card):
    nm = spoken_name(card.get('name'))
