def phase_of(bal, today):
    sd = parse_ddmmyyyy(bal.get('statementDate'))
    nsd = parse_ddmmyyyy(bal.get('nextStatementDate'))
    due = parse_ddmmyyyy(bal.get('lastPayDate'))
    if sd is None:
        return 'no_statement'
    if today == sd or (nsd is not None and today == nsd):
        return 'cut_day'
    if due is not None and today > due:
        return 'after_due'
    return 'normal'


def reading(card, bal, today, focus):
    """returns (text, kind) kind: debt | nodebt"""
    intro = card_intro(card)
    ph = phase_of(bal, today)
    blocks = []
    for c in CUR_ORDER:
